import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    # Ignore leading blank lines, but retain blank records after the header.
    for header in records:
        if header:
            break
    else:
        return {"columns": [], "rows": []}

    rows = list(records)
    width = max(11, len(header), max((len(row) for row in rows), default=0))

    # Pad short records and widen the header rather than dropping extra fields.
    header.extend([""] * (width - len(header)))
    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": header, "rows": rows}
